\begin{definition}[Maurer's generic group model]
Let $p$ be a prime. Each participant $\mathsf{P}$ holds a private array $\mathsf{Arr}_{\mathsf{P}}$ with entries in $\mathbb{Z}_p$, initialized so that $\mathsf{Arr}_{\mathsf{P}}[1] = 1$ and every other index is empty; let $e$ denote the largest non-empty index (so $e = 1$ initially). The participant accesses group elements only through the following queries:
\begin{itemize}
  \item $\mathsf{Add}(i_1, i_2, c_1, c_2)$, with $i_1, i_2 \in [e]$ and $c_1, c_2 \in \mathbb{Z}_p$: writes $c_1 \cdot \mathsf{Arr}_{\mathsf{P}}[i_1] + c_2 \cdot \mathsf{Arr}_{\mathsf{P}}[i_2]$ at index $e+1$ and increments $e$. No value is returned.
  \item $\mathsf{Equal}(i_1, i_2)$, with $i_1, i_2 \in [e]$: returns $1$ if $\mathsf{Arr}_{\mathsf{P}}[i_1] = \mathsf{Arr}_{\mathsf{P}}[i_2]$ and $0$ otherwise.
  \item $\mathsf{Zero}(c_1,\dots,c_e)$, with $c_i \in \mathbb{Z}_p$: returns $1$ if $\sum_{i \in [e]} c_i \cdot \mathsf{Arr}_{\mathsf{P}}[i] = 0$ and $0$ otherwise.
  \item $\mathsf{Write}(x)$, for $x \in \mathbb{Z}_p$: writes $x$ at index $e+1$ and increments $e$.
\end{itemize}
A participant never receives a representation of a group element: the only information it learns from its array is the answers to its $\mathsf{Equal}$ and $\mathsf{Zero}$ queries. The cost of a participant is its number of queries; local computation is free.
\end{definition}

\begin{definition}[Four-party NIKE in Maurer's generic group model]
Fix parameters $\alpha, \beta, \gamma$, publicly known and fixed in advance. Four parties $\mathsf{P}_1,\dots,\mathsf{P}_4$ each receive $1^\lambda$ and $p$, sample private randomness $\mathsf{r}_i$, and each hold a private array as above, all over the same $\mathbb{Z}_p$. The protocol has two rounds.
\begin{enumerate}
  \item Party $\mathsf{P}_i$ interacts with its array, then simultaneously (i) broadcasts a string $\mathsf{m}_i$ and (ii) issues $\mathsf{copy}(\gamma)$, which appends the last $\gamma$ entries $\overline{\mathsf{q}}_i = (\mathsf{q}_{i,1},\dots,\mathsf{q}_{i,\gamma})$ of $\mathsf{Arr}_{\mathsf{P}_i}$ to the end of every other party's array, in a fixed canonical order. Set $\mathsf{tran} := (\mathsf{m}_1,\dots,\mathsf{m}_4)$.
  \item Each party then makes exactly $\alpha$ further $\mathsf{Add}$ queries and $\beta$ further $\mathsf{Zero}$ queries to its own array, and designates one entry of its array as its key $\mathsf{key}_i \in \mathbb{Z}_p$.
\end{enumerate}
The protocol has \emph{completeness error} $\delta$ if $\Pr[\mathsf{key}_1 = \mathsf{key}_2 = \mathsf{key}_3 = \mathsf{key}_4] \ge 1 - \delta$ over the parties' randomness.

The eavesdropper $\mathsf{E}$ receives $\mathsf{tran}$ and holds its own array containing $1$ followed by the $4\gamma$ broadcast elements $(\overline{\mathsf{q}}_1,\dots,\overline{\mathsf{q}}_4)$ in the canonical order; it may make its own $\mathsf{Add}$, $\mathsf{Equal}$ and $\mathsf{Zero}$ queries. $\mathsf{E}$ \emph{wins} if it outputs an index $j$ of its array with $\mathsf{Arr}_{\mathsf{E}}[j] = \mathsf{key}_1$, and it has \emph{advantage} $\rho$ if it wins with probability at least $1/p + \rho$.
\end{definition}

candidate.formal_statement_latex:
There exist a prime family $p = p(\lambda)$, a function $n = n(\lambda)$ with $n(\lambda) \to \infty$, parameters $\alpha, \beta, \gamma \le \tilde{O}(n)$, and a four-party NIKE protocol $\Pi$ in Maurer's generic group model over $\mathbb{Z}_p$ (in the sense of the definition above) such that:
\begin{enumerate}
  \item \textbf{Efficiency.} Each party makes at most $\tilde{O}(n(\lambda))$ queries to its array, across both rounds.
  \item \textbf{Correctness.} $\Pi$ has completeness error $\mathrm{negl}(\lambda)$, i.e. $\Pr[\mathsf{key}_1 = \mathsf{key}_2 = \mathsf{key}_3 = \mathsf{key}_4] \ge 1 - \mathrm{negl}(\lambda)$.
  \item \textbf{Quadratic security.} For every function $q$ with $q(n) = o(n^2)$, every computationally unbounded eavesdropper $\mathsf{E}$ making at most $q(n(\lambda))$ queries has advantage $\rho(\lambda) = o(1)$ as $\lambda \to \infty$.
\end{enumerate}
